import type { Vec3 } from '../core/math';
import { Rng } from '../core/rng';
import { NavGrid, NAV_NONE } from '../world/NavGrid';
import { objectNear, type WorldObject } from '../world/Segmentation';
import { OCC_THRESHOLD, type VoxelGrid } from '../world/VoxelGrid';

/**
 * Hiding-spot search. A candidate spot is any reachable nav node. It is scored
 * by how well it conceals a crouching pet from the seeker now and from the
 * places the seeker is likely to walk to, plus some "personality" terms
 * (cosy spots under/inside things, novelty, a reasonable distance).
 */

export type SpotKind = 'under' | 'inside' | 'behind' | 'atop' | 'corner';

export interface HideSpot {
  node: number;
  pos: Vec3;
  kind: SpotKind;
  object: WorldObject | null;
  /** Fraction of the pet hidden from the seeker's position at hide time. */
  hiddenNow: number;
  /** Fraction of sampled seeker viewpoints the pet is hidden from. */
  coverage: number;
  pathCost: number;
  score: number;
  /** Yaw the pet should face while hiding (towards the open side, to peek). */
  faceYaw: number;
}

export interface HideOptions {
  /** 0 = easy (findable from many places), 1 = hard. */
  difficulty: number;
  maxPathCost: number;
  previous: Vec3[];
  rng: Rng;
  objects: WorldObject[];
  eyeHeight: number;
  /** Minimum fraction hidden from the seeker right now (default 0.85). */
  minHiddenNow?: number;
  /** Body sample offsets of the actual hiding poses (pet facing +Z), see measurePoseSamples. */
  poseSamples?: { hide: Vec3[]; hideLow: Vec3[] };
  /**
   * Spot safety (see spotSafety): minimum distance (m) from the spot to
   * anything solid at body height, and the share of the crouched body's
   * voxels that must have been seen empty. Defaults: DEFAULT_SPOT_SAFETY.
   */
  minClearance?: number;
  minSeenFree?: number;
  /** Minimum distance (m) to space never observed at body height under structure seen higher up (a blank wall's unmeasured base). */
  minKnownClearance?: number;
  /** Minimum distance (m) to structure not observed for `staleSeconds` (s): it sits where an older, possibly drifted frame put it. */
  minStaleClearance?: number;
  staleSeconds?: number;
  /**
   * Maximum age (s) of the "seen empty" evidence where the pet's body goes
   * (VoxelGrid.colFree: when the low band of the spot's columns was last
   * carved). Old free space sits where an older, possibly drifted frame put
   * it: the inside of a sofa can be "seen empty" from a minute ago.
   * Infinity = off.
   */
  maxFreeAge?: number;
}

/**
 * Hiding spots hug cover, and cover is where the map is least sure of
 * itself: a wall or sofa remembered from minutes ago sits wherever the
 * camera's frame put it then, often 10–20cm from where it is now, and the
 * base of a blank wall or a dark sofa is often never measured at all. In the
 * large-area benchmark (drifting tracker) the spots that put the pet inside
 * furniture were within ~15cm of mapped structure, or right next to space
 * never observed at body height at the foot of something seen higher up.
 * So: keep 15cm to anything solid, 20cm to structure not seen for 30s, 14cm
 * to the never-observed foot of structure, and require the body's own space
 * to have been seen empty. (The nav graph only needs 10cm of clearance and
 * half the body seen empty: fine for walking past, not for parking the pet
 * there for a whole round.) Ten homes, house-hard, the same walks: hide
 * spots with the pet inside furniture 4.4% → 2.1%, rounds with no spot at
 * all 5.4% → 6.9% (the game then relaxes to RELAXED_SPOT_SAFETY). Fresh
 * structure keeps the plain 15cm: a margin from everything pushes spots out
 * into the open (Hopper visibly less hidden in the single-room game tests).
 * And the body's space must have been seen empty in the last minute
 * (maxFreeAge, VoxelGrid.colFree): free space seen longer ago sits where an
 * older, possibly drifted frame put it — the inside of a sofa "seen empty"
 * from across the room minutes ago. Same ten homes: spots inside furniture
 * 2.2% → 0.4% (paired −1.9 ± 0.4 points), rounds with no spot 6.0 → 6.3%.
 */
export const DEFAULT_SPOT_SAFETY = { minClearance: 0.15, minSeenFree: 0.8, minKnownClearance: 0.14, minStaleClearance: 0.2, staleSeconds: 30, maxFreeAge: 60 };
/** Fallback when no spot passes DEFAULT_SPOT_SAFETY (better a slightly riskier spot than no game). */
export const RELAXED_SPOT_SAFETY = { minClearance: 0.15, minSeenFree: 0.6, minKnownClearance: 0.1, minStaleClearance: 0.15, staleSeconds: 30, maxFreeAge: Infinity };

/**
 * Distances (m, capped at 0.3) from nav node `a` to the nearest solid voxel
 * at body height and to the nearest voxel never observed there under
 * something seen higher up (unknown: neither seen empty nor solid — e.g. the
 * base of a blank wall), and the share of its body voxels seen empty.
 */
export function spotSafety(g: VoxelGrid, nav: NavGrid, a: number, staleSeconds = 30): { clearance: number; staleClearance: number; knownClearance: number; seenFree: number; freeAge: number } {
  const p = nav.pos(a);
  const ci = nav.ni[a], ck = nav.nk[a], j0 = g.cellY(p.y + 0.001);
  const sh = g.updateShadow();
  const R = Math.ceil(0.3 / g.res);
  // Occupied voxels whose occupancy evidence is older than this time code are
  // "stale" (see VoxelGrid.hitTime; grids without hit times have none).
  const ht = g.hitTime, staleBefore = g.stamp - staleSeconds;
  let best = R * R + 1, bestS = R * R + 1, bestU = R * R + 1, seen = 0, total = 0, freeAge = 0;
  const cf = g.colFree;
  for (let dk = -R; dk <= R; dk++)
    for (let di = -R; di <= R; di++) {
      const d2 = di * di + dk * dk;
      const body = d2 <= 1;
      if (d2 >= best && d2 >= bestS && d2 >= bestU && !body) continue;
      const i = ci + di, k = ck + dk;
      if (body && cf && i >= 0 && k >= 0 && i < g.nx && k < g.nz) {
        const c = cf[k * g.nx + i];
        freeAge = Math.max(freeAge, c ? g.stamp - c : Infinity);
      }
      // Unknown space counts only at the foot of something seen higher up
      // (the base of a wall or sofa the depth never measured): the space
      // behind furniture is often never observed either, and that is where
      // hiding spots are.
      let under = -1;
      for (let j = j0 + 1; j <= j0 + 3; j++) {
        if (!g.inBounds(i, j, k)) continue;
        const n = g.idx(i, j, k), v = g.data[n];
        if (body) {
          total++;
          if (v <= -2) seen++;
        }
        if (v >= 10 || sh[n] === 1 || g.isTransient(n)) {
          best = Math.min(best, d2);
          if (ht && v > OCC_THRESHOLD && (ht[n] & 0xffff) < staleBefore) bestS = Math.min(bestS, d2);
        } else if (v > -2 && d2 < bestU) {
          if (under < 0) {
            under = 0;
            for (let jj = j0 + 4; jj <= j0 + 30 && jj < g.ny; jj++)
              if (g.data[g.idx(i, jj, k)] > OCC_THRESHOLD) {
                under = 1;
                break;
              }
          }
          if (under) bestU = d2;
        }
      }
    }
  const m = (d2: number) => Math.min(Math.sqrt(d2), R) * g.res;
  return { clearance: m(best), staleClearance: m(bestS), knownClearance: m(bestU), seenFree: total ? seen / total : 0, freeAge };
}

/** Body sample points of a crouched pet standing at `p` (relative offsets). */
export const HIDE_SAMPLES: Vec3[] = [
  { x: 0, y: 0.07, z: 0 },
  { x: 0, y: 0.14, z: 0.03 },
  { x: 0.07, y: 0.07, z: 0 },
  { x: -0.07, y: 0.07, z: 0 },
  { x: 0, y: 0.07, z: 0.07 },
  { x: 0, y: 0.07, z: -0.07 },
  { x: 0, y: 0.19, z: 0 },
];

/** Fraction of `points` with an unobstructed line of sight from `eye`. */
export function visibleFraction(g: VoxelGrid, eye: Vec3, points: Vec3[], skipEnd = 0.04): number {
  let vis = 0;
// Only observed obstacles count as cover: unknown space is assumed see-through,
  // so Hopper never "hides" behind something we merely guessed is there.
  for (const q of points) if (g.segmentClear(eye, q, skipEnd)) vis++;
  return vis / points.length;
}

/**
 * Like `visibleFraction`, but stops casting rays once more than `limit` of the
 * points are visible, returning a value above `limit`. Exact at or below it.
 */
export function visibleFractionUpTo(g: VoxelGrid, eye: Vec3, points: Vec3[], limit: number, skipEnd = 0.04): number {
  const n = points.length;
  let vis = 0;
  for (const q of points) {
    if (g.segmentClear(eye, q, skipEnd)) vis++;
    if (vis > limit * n) break;
  }
  return vis / n;
}

/** Exactly `visibleFraction(...) < frac`, deciding with as few rays as it can. */
export function visibleLessThan(g: VoxelGrid, eye: Vec3, points: Vec3[], frac: number, skipEnd = 0.04): boolean {
  const n = points.length, need = frac * n;
  let vis = 0;
  for (let i = 0; i < n; i++) {
    if (g.segmentClear(eye, points[i], skipEnd)) vis++;
    if (vis >= need) return false;
    if (vis + (n - i - 1) < need) return true;
  }
  return vis < need;
}

export function samplesAt(p: Vec3, offsets: Vec3[] = HIDE_SAMPLES, yaw = 0): Vec3[] {
  const c = Math.cos(yaw), s = Math.sin(yaw);
  // Rotation about +Y by yaw (pet's +Z forward maps to (sin yaw, 0, cos yaw)).
  return offsets.map((o) => ({ x: p.x + o.x * c + o.z * s, y: p.y + o.y, z: p.z - o.x * s + o.z * c }));
}

/** Spread-out seeker viewpoints on open floor (farthest-point sampling). */
export function seekerViewpoints(nav: NavGrid, eyeHeight: number, count: number, rng: Rng, floorY: number): Vec3[] {
  const open: number[] = [];
  for (let a = 0; a < nav.count; a++) {
    if (Math.abs(nav.ny[a] - floorY) > 0.05) continue;
    if (nav.headroom[a] < 0.45 || nav.wallDist[a] < 0.3) continue;
    if ((nav.ni[a] + nav.nk[a]) % 3 !== 0) continue;
    open.push(a);
  }
  if (!open.length) return [];
  const pts: Vec3[] = [];
  const first = open[rng.int(0, open.length - 1)];
  pts.push(nav.pos(first));
  const dmin = new Float32Array(open.length).fill(Infinity);
  while (pts.length < count) {
    const last = pts[pts.length - 1];
    let best = -1, bd = -1;
    for (let q = 0; q < open.length; q++) {
      const p = nav.pos(open[q]);
      const d = Math.hypot(p.x - last.x, p.z - last.z);
      if (d < dmin[q]) dmin[q] = d;
      if (dmin[q] > bd) {
        bd = dmin[q];
        best = q;
      }
    }
    if (best < 0 || bd < 0.3) break;
    pts.push(nav.pos(open[best]));
  }
  return pts.map((p) => ({ x: p.x, y: p.y + eyeHeight, z: p.z }));
}

export function classifySpot(g: VoxelGrid, nav: NavGrid, a: number, floorY: number): { kind: SpotKind; walls: number; openYaw: number; covered: boolean } {
  const p = nav.pos(a);
  const i = nav.ni[a], k = nav.nk[a];
  const j = g.cellY(p.y + 0.001);
  // Overhead cover within ~1.1m.
  let covered = false;
  for (let jj = j + 3; jj < Math.min(g.ny, j + Math.ceil(1.1 / g.res)); jj++)
    if (g.occ(i, jj, k)) {
      covered = true;
      break;
    }
  // Walls around at body height, in 8 directions within 0.3m.
  let walls = 0;
  let ox = 0, oz = 0;
  const R = Math.ceil(0.3 / g.res);
  for (let d = 0; d < 8; d++) {
    const ang = (d / 8) * Math.PI * 2;
    const cx = Math.cos(ang), cz = Math.sin(ang);
    let hit = false;
    for (let s = 1; s <= R && !hit; s++) {
      const ii = Math.round(i + cx * s), kk = Math.round(k + cz * s);
      for (let jj = j + 1; jj <= j + 4; jj++)
        if (g.occ(ii, jj, kk)) {
          hit = true;
          break;
        }
    }
    if (hit) walls++;
    else {
      ox += cx;
      oz += cz;
    }
  }
  // Yaw such that the pet's +Z faces the open direction (atan2(x, z)).
  const openYaw = Math.atan2(ox, oz);
  const elevated = p.y - floorY > 0.25;
  let kind: SpotKind;
  if (walls >= 6) kind = 'inside';
  else if (covered) kind = 'under';
  else if (elevated) kind = 'atop';
  else if (walls >= 3) kind = 'corner';
  else kind = 'behind';
  return { kind, walls, openYaw, covered };
}

export function findHideSpots(nav: NavGrid, petPos: Vec3, seekerEye: Vec3, opts: HideOptions, floorY: number, topN = 5): HideSpot[] {
  const g = nav.g;
  const start = nav.nearest(petPos);
  if (start === NAV_NONE) return [];
  const { cost } = nav.search(start, NAV_NONE, opts.maxPathCost);
  const rng = opts.rng;
  const S = { ...DEFAULT_SPOT_SAFETY };
  for (const k of Object.keys(S) as (keyof typeof S)[]) if (opts[k] !== undefined) S[k] = opts[k]!;

  // Stage 1: cheap filter — reachable, hidden from the seeker right now.
  type Cand = { a: number; p: Vec3; hiddenNow: number; pre: number; cls: ReturnType<typeof classifySpot>; pts: Vec3[] };
  const cands: Cand[] = [];
  const J = 0.15;
  // ...and ±10cm up/down: rays that just graze the top edge of a seat or table
  // are exactly where a 5cm map is least sure.
  const jitterEyes = [
    seekerEye,
    ...[[J, 0], [-J, 0], [0, J], [0, -J]].map(([dx, dz]) => ({ x: seekerEye.x + dx, y: seekerEye.y, z: seekerEye.z + dz })),
    { x: seekerEye.x, y: seekerEye.y + 0.1, z: seekerEye.z },
    { x: seekerEye.x, y: seekerEye.y - 0.1, z: seekerEye.z },
  ];
  for (let a = 0; a < nav.count; a++) {
    if (!(cost[a] <= opts.maxPathCost)) continue;
    if ((nav.ni[a] + 2 * nav.nk[a]) % 2 !== 0) continue; // thin out
    const p = nav.pos(a);
    const dSeeker = Math.hypot(p.x - seekerEye.x, p.z - seekerEye.z);
    if (dSeeker < 1.0) continue;
    const minHidden = opts.minHiddenNow ?? 0.85;
    if (minHidden > 0.5 && visibleFractionUpTo(g, seekerEye, samplesAt(p), 0.5) > 0.5) continue; // quick reject
    const cls = classifySpot(g, nav, a, floorY);
    // Walled in on (nearly) every side *and* covered: not a nook a pet could
    // get into but a hole the map left inside furniture (a couch's dark
    // fabric that depth couldn't see). Real "inside" spots — baskets, boxes —
    // are open from above.
    if (cls.kind === 'inside' && cls.covered) continue;
    const safe = spotSafety(g, nav, a, S.staleSeconds);
    if (safe.clearance < S.minClearance - 1e-6 || safe.staleClearance < S.minStaleClearance - 1e-6 || safe.knownClearance < S.minKnownClearance - 1e-6 || safe.seenFree < S.minSeenFree || safe.freeAge > S.maxFreeAge) continue;
    const low = cls.kind === 'under' || cls.kind === 'inside';
    const offs = opts.poseSamples ? (low ? opts.poseSamples.hideLow : opts.poseSamples.hide) : HIDE_SAMPLES;
    const pts = samplesAt(p, offs, cls.openYaw);
    // Measured edges are off by a few cm (sensor noise, 5cm voxels): judge
    // "hidden now" on a body raised by a 6cm safety margin.
    const ptsUp = pts.map((q) => ({ x: q.x, y: q.y + 0.06, z: q.z }));
    // Robust to map quantisation and to the seeker shifting a little: must be
    // hidden from the eye and from points ~15cm around it.
    let hiddenNow = 1;
    for (const e of jitterEyes) {
      hiddenNow = Math.min(hiddenNow, 1 - visibleFractionUpTo(g, e, ptsUp, 1 - minHidden));
      if (hiddenNow < minHidden) break;
    }
    if (hiddenNow < minHidden) continue;
    let pre = 0;
    pre += { inside: 1.0, under: 0.8, corner: 0.5, behind: 0.3, atop: 0.4 }[cls.kind];
    pre += Math.min(cls.walls, 5) * 0.05;
    pre -= Math.abs(dSeeker - 2.8) * 0.12;
    pre += hiddenNow * 1.5; // matters when criteria are relaxed
    cands.push({ a, p, hiddenNow, pre, cls, pts });
  }
  cands.sort((x, y) => y.pre - x.pre);
  const shortlist = cands.slice(0, 300);

  // Stage 2: coverage over likely seeker viewpoints.
  // Standing and crouching viewpoints: a spot only counts as findable from a
  // viewpoint if most of the pet would be visible from there.
  const standing = seekerViewpoints(nav, opts.eyeHeight, 16, new Rng(1234), floorY);
  const views = [...standing, ...standing.filter((_, i) => i % 2 === 0).map((v) => ({ ...v, y: floorY + 0.85 }))];
  // Target coverage: easy → hidden from ~55% of the room, hard → ~90%.
  const target = 0.55 + 0.35 * opts.difficulty;
  const spots: HideSpot[] = shortlist.map((c) => {
    const pts = c.pts;
    let hiddenFrom = 0;
    for (const v of views) if (visibleLessThan(g, v, pts, 0.5)) hiddenFrom++;
    const coverage = views.length ? hiddenFrom / views.length : 1;
    let score = c.pre;
    score -= Math.abs(coverage - target) * 2.2;
    // Never pick a spot that literally nobody can see (unfun): penalise full coverage on easy.
    if (coverage > 0.97) score -= 0.6 * (1 - opts.difficulty);
    // Novelty: avoid previous hiding places.
    for (const q of opts.previous) {
      const d = Math.hypot(q.x - c.p.x, q.z - c.p.z);
      if (d < 1.2) score -= (1.2 - d) * 1.2;
    }
    score -= cost[c.a] * 0.03;
    score += rng.range(0, 0.35);
    return {
      node: c.a,
      pos: c.p,
      kind: c.cls.kind,
      object: objectNear(opts.objects, c.p),
      hiddenNow: c.hiddenNow,
      coverage,
      pathCost: cost[c.a],
      score,
      faceYaw: c.cls.openYaw,
    };
  });
  spots.sort((x, y) => y.score - x.score);
  // Return a diverse top list (no two within 0.6m).
  const out: HideSpot[] = [];
  for (const s of spots) {
    if (out.some((o) => Math.hypot(o.pos.x - s.pos.x, o.pos.z - s.pos.z) < 0.6)) continue;
    out.push(s);
    if (out.length >= topN) break;
  }
  return out;
}

export function describeSpot(s: Pick<HideSpot, 'kind' | 'object'>): string {
  const obj = s.object ? s.object.label : null;
  switch (s.kind) {
    case 'under':
      return obj ? `under the ${obj}` : 'under something';
    case 'inside':
      return obj ? `inside the ${obj}` : 'in a cosy nook';
    case 'atop':
      return obj ? `on top of the ${obj}` : 'up high';
    case 'corner':
      return obj ? `tucked beside the ${obj}` : 'in a corner';
    default:
      return obj ? `behind the ${obj}` : 'behind something';
  }
}
